 const selectionCohortPanel='<article class="panel detail-card"><h3>Qualité réelle de la Sélection</h3><p class="muted">Un premier signal par token. Comparaison des meilleurs, de la watchlist et d’un petit échantillon témoin.</p><div class="table-wrap"><table><thead><tr><th>Cohorte</th><th>Horizon</th><th>Évalués</th><th>Hausse ≥15%</th><th>Rendement moyen</th><th>Pertes ≤−20%</th><th>Drawdown moyen</th><th>Échecs liquidité</th></tr></thead><tbody>'+cohortRows+'</tbody></table></div><p class="footnote">Tokens suivis : '+(state.selectionPerformance?.totalTracked||0)+' · '+(state.selectionPerformance?.status==='prospective_sample'?'Échantillon prospectif en cours':'Collecte en cours')+' · '+esc(state.selectionPerformance?.updatedAt||'Aucune mesure pour le moment')+'</p><small class="footnote">'+esc(state.selectionPerformance?.method||'Les résultats apparaîtront après les premières observations. Les snapshots manquants ne sont pas comptés comme pertes.')+'</small></article>';
