 const setup=source.configured?'':'<article class="panel detail-card"><h3>Helius non configuré</h3><p>Ajoute HELIUS_API_KEY dans les variables d’environnement FadeHost. Les RPC publics restent disponibles en secours.</p><a class="external-link" href="https://dashboard.helius.dev/" target="_blank" rel="noopener">Ouvrir Helius ↗</a></article>';
 view.innerHTML='<div class="section-heading"><div><h2>Wallets & performances</h2><p class="muted">Analyse locale des wallets suivis à partir des transactions Solana récupérées via Helius.</p></div></div><div class="stat-grid"><article class="panel stat"><span>Wallets suivis</span><strong>'+(data.summary?.trackedWallets||0)+'</strong></article><article class="panel stat"><span>Swaps confirmés</span><strong>'+(data.summary?.confirmedSwaps||0)+'</strong></article><article class="panel stat"><span>Positions clôturées</span><strong>'+(data.summary?.closedPositions||0)+'</strong></article></div>'+setup+'<article class="panel detail-card"><h3>Source on-chain</h3>'+pill(source.connected?'Helius connecté':source.configured?'Helius configuré, attente des données':'RPC publics en secours',source.connected?'good':'warn')+'<p>'+esc(source.mode||'Surveillance on-chain')+'</p><p class="muted">Dernière activité observée : '+date(data.updatedAt)+'</p><small class="footnote">'+esc(data.methodology||'Performances calculées sur les swaps confirmés collectés.')+'</small></article>'+backtestPanel+'<article class="panel detail-card"><h3>Convergence sur des tokens</h3>'+(signals||'<p class="muted">Pas encore de convergence suffisante entre plusieurs wallets fiables.</p>')+'</article><article class="panel detail-card"><h3>Classement des wallets observés</h3>'+(cards||'<p class="muted">Le classement se construit à mesure que les wallets manuels, acheteurs précoces et créateurs sont suivis.</p>')+'</article>'+(trades?'<article class="panel detail-card"><h3>Dernières transactions suivies</h3>'+trades+'</article>':'')+'<p class="footnote">Helius fournit les données on-chain, pas une liste de personnalités ni une garantie de rentabilité. Les RPC publics sont utilisés en secours. Les historiques sont partiels; les swaps non confirmés ne comptent pas dans les performances.</p>';
