 +'<article class="panel detail-card"><h3>Positions ouvertes</h3><div class="table-wrap"><table><thead><tr><th>Token</th><th>Entrée</th><th>Dernier prix</th><th>Variation brute</th><th>Ouverture</th></tr></thead><tbody>'+rows+'</tbody></table></div></article>'
