function renderResults(){
 const best=state.selectionPerformance?.groups?.best||{};
 const horizons=best.horizons||{};
 const one=horizons['1h']||{},six=horizons['6h']||{},day=horizons['24h']||{},week=horizons['7d']||{};
 const rate=one.positive15Pct==null?'—':one.positive15Pct+'%';
 const average=one.averageReturnPct==null?'—':(one.averageReturnPct>0?'+':'')+one.averageReturnPct+'%';
 const sample=Number(one.resolved)||0;
 const sampleLabel=sample<30?'Échantillon encore limité':'Échantillon en cours de consolidation';
 const adaptive=state.selection?.adaptiveThreshold||{threshold:68,validated:false,reason:'Pas encore assez de résultats indépendants pour ajuster le seuil.'};
 const metric=(label,value,detail)=>'<article class="panel stat"><span>'+label+'</span><strong>'+value+'</strong><small>'+detail+'</small></article>';
 view.innerHTML='<div class="section-heading"><div><h2>Résultats de M2</h2><p class="muted">Est-ce que les trouvailles sélectionnées ont réellement progressé ?</p></div></div><article class="panel performance-hero"><p>Taux de réussite à 1 heure</p><strong>'+rate+'</strong><small>'+sample+' trouvailles évaluées · réussite = hausse d’au moins 15 % après environ 1 heure.</small></article><div class="stat-grid simple-stats">'+metric('Rendement moyen à 1 h',average,'Variation moyenne du prix')+metric('Hausse à 6 h',six.positive15Pct==null?'—':six.positive15Pct+'%',(six.resolved||0)+' évaluées')+metric('Hausse à 24 h',day.positive15Pct==null?'—':day.positive15Pct+'%',(day.resolved||0)+' évaluées')+'</div><article class="panel detail-card"><h3>Suivi dans le temps</h3><div class="table-wrap"><table><thead><tr><th>Durée</th><th>Évaluées</th><th>Hausse ≥15 %</th><th>Rendement moyen</th><th>Baisses ≤−20 %</th></tr></thead><tbody>'+[['1 heure',one],['6 heures',six],['24 heures',day],['7 jours',week]].map(([label,x])=>'<tr><td>'+label+'</td><td>'+(x.resolved||0)+'</td><td>'+(x.positive15Pct==null?'—':x.positive15Pct+'%')+'</td><td>'+(x.averageReturnPct==null?'—':(x.averageReturnPct>0?'+':'')+x.averageReturnPct+'%')+'</td><td>'+(x.loss20Pct==null?'—':x.loss20Pct+'%')+'</td></tr>').join('')+'</tbody></table></div><p class="footnote">'+sampleLabel+'. Une seule entrée par token sélectionné; les observations manquantes ne sont pas comptées comme des pertes. Les résultats sont basés sur les prix observés, sans frais, slippage ni garantie d’exécution. Le score M2 n’est pas une probabilité de hausse.</p></article><article class="panel detail-card"><h3>Le bot apprend-il ?</h3><p>Seuil de sélection actuel : <b>'+adaptive.threshold+'/100</b> · '+(adaptive.validated?'calibré sur validation indépendante':'seuil prudent par défaut')+'</p><p>'+esc(adaptive.reason||'Le seuil ne change que lorsque les résultats indépendants sont suffisants.')+'</p><p class="muted">M2 ajuste uniquement le seuil après validation ; il ne réécrit pas ses poids sur un petit échantillon.</p><p class="muted">Dernière mise à jour : '+date(state.selectionPerformance?.updatedAt)+'</p></article>';
}
function renderMore(){
 const items=[['paper','◷','Paper trading','Simuler les résultats des 5 meilleurs candidats'],['experts','◎','Wallets & performances','Analyser les wallets observés via Helius'],['backtest','↗','Résultats','Voir si les signaux du bot ont été pertinents'],['alerts','♧','Alertes','Retrouver les alertes envoyées'],['settings','⚙','Paramètres','Vérifier les réglages et les connexions']];
 view.innerHTML='<div class="section-heading"><div><h2>Plus</h2><p class="muted">Les pages utiles en dehors du scanner.</p></div></div><div class="simple-menu">'+items.map(x=>'<button class="panel simple-menu-item" data-go="'+x[0]+'"><span class="module-icon">'+x[1]+'</span><span><b>'+x[2]+'</b><small>'+x[3]+'</small></span><span class="module-state">→</span></button>').join('')+'</div>';
}
function renderSettings(){
 const sources=Object.values(state.overview.sources||{});
 const connected=sources.filter(x=>x.connected).length;
 const total=sources.length;
 const telegram=state.overview.sources?.telegram;
 const settings=state.scannerSettings||{preset:'balanced',minScore:78,minLiquidityUsd:5000,publishOpportunities:true,publishRisks:true};
 view.innerHTML='<div class="section-heading"><div><h2>Réglages du scanner</h2><p class="muted">Choisis ce que le bot repère et publie. Les clés restent protégées dans FadeHost.</p></div></div><div class="simple-status"><article class="panel stat"><span>Scanner</span><strong>'+pill(state.overview.scannerRunning?'Actif':'À vérifier',state.overview.scannerRunning?'good':'warn')+'</strong></article><article class="panel stat"><span>Telegram</span><strong>'+pill(telegram?.connected?'Connecté':telegram?.configured?'Configuré':'Non configuré',telegram?.connected?'good':'warn')+'</strong></article><article class="panel stat"><span>Sources actives</span><strong>'+connected+' / '+total+'</strong></article></div><article class="panel channel-setup scanner-settings-card"><form id="scanner-settings-form" class="scanner-settings-form"><div class="settings-fields"><label>Profil de détection<select name="preset" id="scanner-settings-preset"><option value="prudent" '+(settings.preset==='prudent'?'selected':'')+'>Prudent · moins d’alertes</option><option value="balanced" '+(settings.preset==='balanced'?'selected':'')+'>Équilibré · recommandé</option><option value="large" '+(settings.preset==='large'?'selected':'')+'>Large · plus de candidats</option><option value="custom" '+(settings.preset==='custom'?'selected':'')+'>Personnalisé</option></select></label><label>Score minimum (50 à 95)<input type="number" name="minScore" min="50" max="95" step="1" value="'+esc(settings.minScore)+'" required></label><label>Liquidité minimale en dollars<input type="number" name="minLiquidityUsd" min="500" max="1000000" step="500" value="'+esc(settings.minLiquidityUsd)+'" required></label></div><div class="settings-toggles"><label><input type="checkbox" name="publishOpportunities" '+(settings.publishOpportunities?'checked':'')+'> Publier les opportunités</label><label><input type="checkbox" name="publishRisks" '+(settings.publishRisks?'checked':'')+'> Publier les alertes de risque</label></div><div class="settings-save"><small class="footnote">Le profil Large augmente le nombre de candidats et peut réduire leur qualité moyenne. Aucun achat automatique n’est effectué.</small><button class="primary" type="submit">Enregistrer les réglages</button></div></form></article><p class="footnote">Les changements sont sauvegardés dans les données du bot et appliqués au prochain cycle de scan. Les identifiants et clés API ne sont jamais affichés ici.</p>';
}
function render(page=state.page){
 state.page=page;title.textContent=labels[page]||labels.overview;
 nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===page));
 try{
  ({overview:renderOverview,scanner:()=>renderScanner('scanner'),opportunities:()=>renderScanner('opportunities'),watchlist:renderWatchlist,analysis:renderDetail,smart:renderSmart,security:renderSecurity,social:renderSocial,creators:renderCreators,backtest:renderBacktest,historical:renderHistorical,smartIntel:renderWalletIntel,walletGraph:renderWalletGraph,quality:renderQuality,alerts:renderAlerts,settings:renderSettings,channels:renderChannels,results:renderResults,more:renderMore,paper:renderPaper,experts:renderExperts}[page]||renderOverview)();
  if(state.loadErrors.length)view.insertAdjacentHTML('afterbegin','<div class="notice"><b>Actualisation partielle</b><p>'+state.loadErrors.map(esc).join('<br>')+'</p><small>Nouvelle tentative automatique dans 30 secondes.</small></div>');
 }catch(error){
  console.error('[MEME RADAR UI]',error);
  view.innerHTML='<div class="panel empty-panel"><div class="empty-icon">!</div><h2>Actualisation en cours</h2><p>'+esc(error.message||error)+'</p><small>Nouvelle tentative automatique dans 30 secondes.</small></div>';
 }
}
let dashboardLoadPromise=null;
function setSyncStatus(label,kind='neutral'){
 const badge=$('#sync-status');
 if(!badge)return;
 badge.className='pill '+kind;
 badge.innerHTML='<i></i>'+esc(label);
}
const pageDataLoaders={
 smart:async()=>{const data=await api('/api/wallets');state.wallets=data.wallets||[];state.autoWallets=data.autoWallets||[];},
 creators:async()=>{const data=await api('/api/intelligence/creators');state.creators=data.creators||[];state.creatorFundingClusters=data.fundingClusters||[];},
 backtest:async()=>{const [learning,performance]=await Promise.all([api('/api/learning'),api('/api/selection-performance')]);state.learning=learning;state.selectionPerformance=performance;},
 walletGraph:async()=>{state.walletGraph=await api('/api/intelligence/wallet-graph');},
 quality:async()=>{state.dataQuality=await api('/api/data-quality');},
 smartIntel:async()=>{const data=await api('/api/intelligence/wallets');state.walletIntel=data.wallets||[];state.walletClusters=data.clusters||[];},
 historical:async()=>{state.historical=await api('/api/backtest/historical');},
 launches:async()=>{const data=await api('/api/launches');state.launches=data.tokens||[];},
 experts:async()=>{const [experts,signals]=await Promise.all([api('/api/intelligence/experts'),api('/api/intelligence/wallet-signal-backtest')]);state.experts=experts;state.walletSignalBacktest=signals;},
 paper:async()=>{state.paperTrading=await api('/api/paper-trading');},
 results:async()=>{state.selectionPerformance=await api('/api/selection-performance');}
};
async function openPage(page){
 render(page);
 const loader=pageDataLoaders[page];
 if(!loader)return;
 setSyncStatus('Chargement…','neutral');
 try{await loader();if(state.page===page)render(page);setSyncStatus(state.overview.scannerRunning?'Scanner actif':'Scanner à vérifier',state.overview.scannerRunning?'good':'warn');}
 catch(error){console.error('[MEME RADAR page data]',page,error);if(state.page===page)view.insertAdjacentHTML('afterbegin','<div class="notice"><b>Données temporairement indisponibles</b><p>'+esc(error.message||error)+'</p></div>');setSyncStatus('Données indisponibles','warn');}
}
async function load(options={}){
 if(dashboardLoadPromise)return dashboardLoadPromise;
 setSyncStatus('Actualisation…','neutral');
 dashboardLoadPromise=(async()=>{
  const coreJobs=[['Vue générale','/api/overview'],['Tokens','/api/tokens?limit=200'],['Alertes','/api/alerts'],['Watchlist','/api/watchlist'],['Sélection','/api/selection'],['Canaux','/api/telegram/channels'],['Réglages','/api/scanner-settings']];
  const coreResults=await Promise.allSettled(coreJobs.map(([,url])=>api(url)));
  state.loadErrors=[];
  for(let i=0;i<coreResults.length;i++){
   const result=coreResults[i];
   if(result.status==='rejected'){state.loadErrors.push(coreJobs[i][0]+': '+(result.reason?.message||'Erreur inconnue'));continue;}
   const data=result.value;
   if(i===0)state.overview=data;
   if(i===1)state.tokens=data.tokens||[];
   if(i===2)state.alerts=data.alerts||[];
   if(i===3)state.watchlist=data.watchlist||[];
   if(i===4)state.selection=data;
   if(i===5)state.channels=data.channels||[];
   if(i===6)state.scannerSettings=data.settings||null;
  }
  const coreFailures=coreResults.filter(x=>x.status==='rejected').length;
  setSyncStatus(coreFailures?'Données partielles':state.overview.scannerRunning?'Scanner actif':'Scanner à vérifier',coreFailures?'warn':state.overview.scannerRunning?'good':'warn');
  render(state.page);

 })();
 try{return await dashboardLoadPromise;}
 finally{dashboardLoadPromise=null;}
}
async function runButtonAction(button,busyLabel,action){
 if(button?.disabled)return;
 const originalLabel=button?.textContent||'';
 if(button){button.disabled=true;button.setAttribute('aria-busy','true');if(busyLabel)button.textContent=busyLabel;}
 setSyncStatus(busyLabel||'Action en cours…','neutral');
 try{await action();}
 catch(error){console.error('[MEME RADAR action]',error);setSyncStatus('Action impossible','bad');alert(error?.message||'Cette action a échoué. Réessaie.');}
 finally{if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.textContent=originalLabel;}}
}
async function refreshWalletData(){
 const data=await api('/api/wallets');
 state.wallets=data.wallets||[];
 state.autoWallets=data.autoWallets||[];
}
async function openToken(mint,social=false,button=null){
 return runButtonAction(button,'Ouverture…',async()=>{
  const suffix=social?'?social=true':'';
  const data=await api('/api/token/'+encodeURIComponent(mint)+suffix);
  state.selected=data.token;
  if(social)state.selected.socialData=data.social;
  render('analysis');
 });
}
async function scan(button=$('#refresh-tokens')){
 return runButtonAction(button,'Scan…',async()=>{
  await api('/api/scan',{method:'POST',body:'{}'});
  await load({full:false});
  setSyncStatus('Scan terminé','good');
 });
}
async function toggleWatch(mint,button){
 return runButtonAction(button,'Mise à jour…',async()=>{
  const removing=state.watchlist.includes(mint);
  const data=removing
   ?await api('/api/watchlist/'+encodeURIComponent(mint),{method:'DELETE'})
   :await api('/api/watchlist',{method:'POST',body:JSON.stringify({mint})});
  state.watchlist=data.watchlist||state.watchlist;
  await load({full:false});
  setSyncStatus(removing?'Retiré des favoris':'Ajouté aux favoris','good');
 });
}
async function removeWallet(address,button){
 return runButtonAction(button,'Suppression…',async()=>{
  await api('/api/wallets/'+encodeURIComponent(address),{method:'DELETE'});
  await refreshWalletData();
  render(state.page);
  setSyncStatus('Wallet supprimé','good');
 });
}
nav.addEventListener('click',e=>{const target=e.target.closest?.('[data-view]');if(target)openPage(target.dataset.view);});
view.addEventListener('click',async e=>{
 const target=e.target.closest?.('button');
 if(!target)return;
 if(target.id==='refresh-tokens')return scan(target);
 if(target.id==='retry-dashboard'){dashboardBooted=false;return bootDashboard();}
 if(target.hasAttribute('data-token'))return openToken(target.dataset.token,false,target);
 if(target.hasAttribute('data-watch'))return toggleWatch(target.dataset.watch,target);
 if(target.hasAttribute('data-go'))return openPage(target.dataset.go);
 if(target.hasAttribute('data-channel-test'))return runButtonAction(target,'Test…',async()=>{await api('/api/telegram/channels/test',{method:'POST',body:JSON.stringify({chatId:target.dataset.channelTest})});setSyncStatus('Message test envoyé','good');});
 if(target.hasAttribute('data-channel-toggle'))return runButtonAction(target,'Mise à jour…',async()=>{const id=target.dataset.channelToggle;const data=await api('/api/telegram/channels/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({enabled:target.dataset.enabled==='true'})});state.channels=data.channels||[];render('channels');setSyncStatus('Canal mis à jour','good');});
 if(target.hasAttribute('data-channel-remove'))return runButtonAction(target,'Suppression…',async()=>{const id=target.dataset.channelRemove;const data=await api('/api/telegram/channels/'+encodeURIComponent(id),{method:'DELETE'});state.channels=data.channels||[];render('channels');setSyncStatus('Canal supprimé','good');});
 if(target.hasAttribute('data-remove-wallet'))return removeWallet(target.dataset.removeWallet,target);
 if(target.hasAttribute('data-paper-toggle'))return runButtonAction(target,'Mise à jour…',async()=>{const data=await api('/api/paper-trading/config',{method:'POST',body:JSON.stringify({enabled:target.dataset.paperToggle==='true'})});state.paperTrading=data;render('paper');setSyncStatus(data.enabled?'Simulation reprise':'Simulation en pause','good');});
});
view.addEventListener('input',e=>{if(e.target.id==='search-token'){state.search=e.target.value;refreshTable();}});
view.addEventListener('change',e=>{if(e.target.id==='sort-token'){state.sort=e.target.value;refreshTable();}if(e.target.id==='scanner-settings-preset'){const presets={prudent:[85,10000],balanced:[78,5000],large:[70,2500]};const preset=presets[e.target.value];if(preset){const form=e.target.form;form.elements.minScore.value=preset[0];form.elements.minLiquidityUsd.value=preset[1];}}});
view.addEventListener('submit',async e=>{
 if(e.target.id==='channel-form'){
  e.preventDefault();const form=e.target;const button=e.submitter||form.querySelector('button[type="submit"]');
  return runButtonAction(button,'Ajout…',async()=>{const data=await api('/api/telegram/channels',{method:'POST',body:JSON.stringify({chatId:form.elements.chatId.value.trim(),label:form.elements.label.value.trim()})});state.channels=data.channels||[];render('channels');setSyncStatus('Canal ajouté','good');});
 }
 if(e.target.id==='scanner-settings-form'){
  e.preventDefault();const form=e.target;const button=e.submitter||form.querySelector('button[type="submit"]');
  return runButtonAction(button,'Enregistrement…',async()=>{
   const data=await api('/api/scanner-settings',{method:'PATCH',body:JSON.stringify({preset:form.elements.preset.value,minScore:Number(form.elements.minScore.value),minLiquidityUsd:Number(form.elements.minLiquidityUsd.value),publishOpportunities:form.elements.publishOpportunities.checked,publishRisks:form.elements.publishRisks.checked})});
   state.scannerSettings=data.settings;await load({full:false});setSyncStatus('Réglages enregistrés','good');
  });
 }
 if(e.target.id!=='wallet-form')return;
 e.preventDefault();
 const form=e.target;
 const button=e.submitter||form.querySelector('button[type="submit"],button:not([type])');
 await runButtonAction(button,'Ajout…',async()=>{
  await api('/api/wallets',{method:'POST',body:JSON.stringify({address:form.elements.address.value.trim(),label:form.elements.label.value.trim()})});
  await refreshWalletData();
  render(state.page);
  setSyncStatus('Wallet ajouté','good');
 });
});
$('#logout').addEventListener('click',async e=>{
 const button=e.currentTarget;
 await runButtonAction(button,'Déconnexion…',async()=>{
  await api('/api/logout',{method:'POST'});
  location.replace('/login');
 });
});

let dashboardRefreshTimer=null;
let dashboardBooted=false;
async function bootDashboard(){
 if(dashboardBooted)return;
 dashboardBooted=true;
 view.innerHTML='<div class="panel empty-panel"><div class="empty-icon">◎</div><h2>Connexion au scanner</h2><p>Chargement des données et de l’état de surveillance…</p></div>';
 try{await load();}catch(error){console.error('[MEME RADAR boot]',error);view.innerHTML='<div class="panel empty-panel"><h2>Connexion impossible</h2><p>'+esc(error.message||error)+'</p><button class="primary" id="retry-dashboard">Réessayer</button></div>';}
 dashboardRefreshTimer=setInterval(()=>{if(!document.hidden)load({full:false}).catch(error=>console.warn('[MEME RADAR refresh]',error));},30000);
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&dashboardBooted)load({full:false}).catch(error=>console.warn('[MEME RADAR resume]',error));});
view.addEventListener('click',e=>{if(e.target.closest('#retry-dashboard')){dashboardBooted=false;bootDashboard();}});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootDashboard,{once:true});
else bootDashboard();
